history = []
for line in HISTORY.strip().splitlines():
    year, category, event_id, title, context, reality, *choices = line.split("|")
    history.append(dict(id=event_id, year=int(year), category=category, title=title, context=context,
                        reality=reality, choices=choices, source=None, historicalChoice=None, step=None))

# Eight mandatory dilemmas per year; each row supplies a new situation for the
# same eight portfolios, followed by three optional domestic events per year.
FUTURE = """
2026|An allied early-warning network|Pacific deterrence rules|Semiconductor supply insurance|Interstate transmission corridors|Emergency hospital reserves|AI rules for federal agencies|A ten-year resilience budget|A national civic-service compact
2027|A contested maritime corridor|Coast Guard readiness|Port automation and American jobs|Gulf Coast storm protection|Rural hospital closures|A cyberattack on water utilities|Disaster insurance and federal exposure|Governors demand a federalism deal
2028|A Pacific security summit|Rules for autonomous weapons|Critical-mineral processing|Long-duration power storage|The next vaccine platform|Election deepfakes|Funding the next administration|Trust in election certification
2029|An arms-control treaty at risk|A North Atlantic standoff|A shipping insurance shock|Securing offshore wind infrastructure|Veterans' mental-health care|Satellite navigation interference|The cost of military readiness|Congressional war-powers oversight
2030|A Taiwan Strait crisis|Protecting civilian shipping|A Pacific trade disruption|A strategic energy reserve review|Emergency medicine supply chains|A national communications outage|Paying for a prolonged crisis|Civil liberties during a security emergency
2031|Opening a crisis hotline|De-escalation or mobilization|Factory conversion contracts|Black-start capacity for the grid|Hospital surge staffing|Cyber norms with rival powers|Oversight of emergency procurement|A coalition for democratic accountability
2032|An international ceasefire conference|Verification teams and peace monitors|Reopening trade routes|Rebuilding damaged energy links|Treating displaced civilians|Restoring trusted communications|An emergency reconstruction fund|A congressional mandate for peace
2033|Security guarantees after the crisis|Stockpile transparency|Veteran-owned small businesses|Retiring fragile fossil infrastructure|Long-term trauma care|An international cyber incident registry|The future of emergency powers|A public inquiry into crisis decisions
2034|A durable Pacific settlement|A new defense posture|Restoring investor confidence|A continental clean-energy agreement|Health security across borders|Civilian control of military AI|Ending extraordinary borrowing|A truth and reconciliation commission
2035|A reconstruction partnership|Removing unexploded hazards|Reviving industrial towns|Power for recovering communities|Rebuilding community clinics|A public digital reconstruction platform|Who finances reconstruction?|Returning emergency authority to Congress
2036|Refugee resettlement agreements|Resilient emergency shelters|Training the reconstruction workforce|Repairing drinking-water systems|Accessible rehabilitation services|Digital identity with privacy rights|Auditing recovery contracts|A compact with tribal governments
2037|Debt relief for fragile partners|Protecting humanitarian routes|Restoring small-business credit|Western drought adaptation|Care for an aging population|Broadband for rebuilding towns|Sharing recovery costs with states|Local participation in reconstruction
2038|An international rebuilding bank|Disaster-response reserve units|A new advanced-manufacturing corridor|Clean heat for low-income homes|Rebuilding the public-health workforce|Open technical standards for recovery|Reconstruction taxes or borrowing?|A veterans and civilian-service compact
2039|Rebuilding trust with former rivals|Independent security inspections|Competition in reconstruction markets|Rivers, dams, and flood resilience|Mental-health access in every county|A secure public-service cloud|Anti-corruption enforcement funding|Affordable housing in rebuilt communities
2040|A North American resilience pact|Cross-border emergency exercises|The next generation of American industry|Modernizing regional power markets|Long-term-care insurance reform|Public control of essential data|A sustainable post-crisis budget|A national dialogue on inequality
2041|A global health-security compact|A civilian disaster command review|Small-town economic diversification|Restoring damaged ecosystems|A new rural-health workforce|Human review of automated benefits|Funding maintenance after reconstruction|Protecting the rights of displaced citizens
2042|A reconstruction legacy summit|The balance between defense and relief|From recovery subsidies to lasting jobs|Energy independence without isolation|The future of community healthcare|Closing the digital-access gap|An independent reconstruction audit|A constitutional review of emergency laws
2043|Reforming international institutions|A treaty on autonomous weapons|A new global trading framework|Sharing clean-energy technology|An international pandemic reserve|Democratic governance of advanced AI|Financing global public goods|Representation in a changed America
2044|A new North American partnership|Security guarantees for smaller states|Fair competition in AI-driven markets|A continental grid agreement|A federal care guarantee debate|The rights of people affected by AI|A new federal revenue settlement|The integrity of the next election
2045|A permanent peace-verification body|Nuclear risk reduction|Worker ownership in automated industries|An American climate-adaptation standard|Lifelong health and disability coverage|Public-interest computing capacity|A long-term debt and investment rule|A new voting-rights agreement
2046|Climate migration agreements|Community disaster reserves|Prosperity beyond the coastal hubs|Water sharing in a warmer West|A national prevention strategy|A constitutional privacy framework|Intergenerational fairness in taxation|Repairing rural and urban divides
2047|Rules for strategic competition|Accountability for security contractors|The future of American entrepreneurship|A just transition for energy workers|A compact for family caregivers|Human responsibility for AI decisions|Social Security in a changing workforce|Civic education for the next generation
2048|A global technology and rights charter|Protecting democratic infrastructure|Sharing productivity gains|A reliable zero-carbon power system|Equal access to advanced medicine|Auditing national digital infrastructure|The next fifty years of public investment|A peaceful transfer of power
2049|The future of American alliances|A final strategic-defense review|Preparing the next economic generation|A national resilience dividend|Healthcare capacity for the next crisis|A public archive of algorithmic decisions|Closing emergency-era liabilities|A citizens' assembly on the national legacy
2050|America and the new world order|A lasting security settlement|The prosperity your choices created|The energy system of your America|The health of the next generation|Technology in service of democracy|The fiscal legacy of your administrations|Your America in 2050
"""

PORTFOLIOS = [
    ("foreignPolicy", "Allies and partners ask Washington for a durable agreement. A wider commitment could strengthen cooperation, but Congress questions its cost and the limits on American freedom of action.", "Fund a sustained diplomatic and allied initiative", "Negotiate a limited, verifiable agreement", "Reduce new international commitments"),
    ("security", "Defense and civilian agencies disagree about readiness, escalation risks, and oversight. Congress demands a plan that protects the country without creating an open-ended emergency.", "Fund accountable readiness and civilian protection", "Pair a limited security response with de-escalation", "Limit new federal security commitments"),
    ("economy", "American employers and workers face another structural adjustment. Federal investment could build new capacity, while critics warn of costly subsidies and favoritism.", "Invest in domestic capacity and worker transition", "Offer targeted support with performance conditions", "Leave most investment decisions to private markets"),
    ("energy", "Utilities, states, and households want reliable, affordable energy and stronger protection against disruption. A federal program could accelerate progress but requires substantial funding.", "Fund a national clean-energy and resilience program", "Negotiate regional upgrades and targeted incentives", "Rely on utility and state investment"),
    ("welfare", "Hospitals, families, and state governments report gaps in care. Washington can expand capacity, negotiate a narrower safety net, or leave the adjustment to existing providers.", "Fund nationwide care capacity and affordable access", "Target assistance at the most vulnerable communities", "Limit new federal care commitments"),
    ("digitalization", "New technology promises better services but raises questions about security, privacy, and accountability. Federal agencies need rules that can survive the next political transition.", "Fund independent oversight and secure public infrastructure", "Pilot standards with transparent evaluation", "Favor voluntary standards and private development"),
    ("budget", "The Treasury presents competing demands on federal resources. Congress must balance lasting investment, reliable services, and the burden placed on future taxpayers.", "Finance a durable investment and revenue settlement", "Phase in a narrower bipartisan fiscal agreement", "Prioritize immediate spending cuts and private provision"),
    ("society", "Governors, community organizations, and congressional leaders disagree about the next national compact. The decision will shape trust, participation, and the balance of federal and local authority.", "Fund a broad rights and community-investment initiative", "Negotiate a focused bipartisan agreement", "Leave further action mainly to states and communities"),
]

future = []
for line in FUTURE.strip().splitlines():
    year_text, *titles = line.split("|")
    year = int(year_text)
    assert len(titles) == 8
    chapter = "crisis prevention and escalation" if year <= 2034 else "reconstruction and renewal" if year <= 2042 else "a new world order"
    for step, (title, portfolio) in enumerate(zip(titles, PORTFOLIOS), start=1):
        category, context, *choices = portfolio
        future.append(dict(id=f"future-scenario-us-{year}-{step}", year=year, category=category, title=title,
            context=f"Fictional {year} scenario — {chapter}.\n\n{title}: {context} Your earlier choices determine the resources and public support available now. Whether earlier crises were contained or escalated, this decision shapes what comes next.",
            choices=choices, reality=None, source=None, historicalChoice=None, step=step))
    for extra, (category, topic) in enumerate([("welfare", "local care services"), ("economy", "small-business recovery"), ("energy", "community resilience")]):
        title = f"{year}: {topic.capitalize()}"
        future.append(dict(id=f"future-us-extra-{year}-{extra}", year=year, category=category, title=title,
            context=f"Fictional {year} domestic scenario. Mayors and governors request federal help with {topic}. They want an answer that fits the national path your administration has chosen.",
            choices=[f"Fund a federal program for {topic}", f"Negotiate targeted matching grants for {topic}", "Leave additional financing to states and private providers"],
            reality=None, source=None, historicalChoice=None, step=None))

if __name__ == "__main__":
    (DEST / "USHistory.json").write_text(json.dumps(history, indent=2, ensure_ascii=False) + "\n")
    (DEST / "USFuture.json").write_text(json.dumps(future, indent=2, ensure_ascii=False) + "\n")
    assert len(history) == 108 and len(future) == 275
    assert all(len(e["choices"]) == 3 for e in history + future)
    print(f"Wrote {len(history)} historical and alternate-history US decisions, {len(future)} fictional future decisions")
